const asyncServiceCallHelper = async (query, ownerId, ownerName, viewOrEditor) => { 
  let options;

  if (viewOrEditor === 'view') {
    options = await _LeanData.FlowBuilderController.getAllOwnerDataRemote(query);
  } else { // editor
    options = await _LeanData.FlowBuilderController.getAllOwnerDataActiveOnlyRemote(query);
  }

  // here, should try to "wrap" options or group them
  // lodash has various utilities
  // and title, etc.; name, label differences
  // groupBy name
  if (Array.isArray(options)) { 
    options.forEach((option) => { 
      if (viewOrEditor === 'view') {
        if (option.Id === ownerId || option.label === ownerName) {
          option.disableSelectedField = true;
        }
      } else { // editor
        if (option.Id === ownerId || option.name === ownerName) {
          option.disableSelectedField = true;
        }
      }
    });

    // sorting order
    let sortingOrder = {'Lead': 0, 'Contact': 1, 'Account': 2, 'Opportunity': 3, 'Case': 4};
    let initials = {'Lead': 'L', 'Contact': 'C', 'Account': 'A', 'Opportunity': 'O', 'Case': 'Ca'};
    let [rr, nonRR] = _.partition(options, (x) => x.attributes.type === 'Round_Robin_Pool__c');

    let optionsGroupedByName = _.groupBy(rr, (x) => x.name); // {'California2': [{California2, Lead}, {California2, Contact}]}
    let optionsList = []; // eventually will be [{name: 'California2', categories: '<span>...</span>', ...}, {name: 'California3': ...}]

    // logic for more needs to be added
    for (let name in optionsGroupedByName) {
      let group = optionsGroupedByName[name];
      let customObjects = []; // eventually will look like ['CustomObject1', ...]
      let categories = []; // eventually will look like ['L', 'C', 'A']
      // casework: is there or is there not standard object?
      let hasStandardObject = false;

      for (let opt of group) {
        if (opt.Object_Type__c in initials) {
          // is a standard object
          hasStandardObject = true;
          categories.push(opt.Object_Type__c);
        } else {
          // has a custom object
          customObjects.push(
            _LeanData.MetaDataController.getObjectMetaDataObject(opt.Object_Type__c, true).label || opt.Object_Type__c
          );
        }
      }

      if (hasStandardObject) {
        // hoverText is for the mouse hover over, "title"
        // we want the full names
        // L C A , then objects
        categories = _.sortBy(categories, (item) => sortingOrder[item]);
        customObjects = customObjects.sort();
        let hoverText = [...categories, ...customObjects].join(', ');

        categories = categories.map((cat) => 
          `<span title="${cat}">${initials[cat]}</span>`
        );
        // need to do for custom objects; n more
        if (customObjects.length > 0) {
          let customObjectsStr = customObjects.join('/');
          categories.push(`<span title="${customObjectsStr}">${customObjects.length} more</span>`);
        }
        group[0].categories = categories.join(' <span class="divider">/</span> '); // this is the string
        group[0].name = hoverText;
        optionsList.push(group[0]); // this is for the objects list
      } else {
        // has no standard object
        customObjects = customObjects.sort();
        let hoverText = [...customObjects].join(', ');

        // sorting order
        let customObjectsStr = customObjects.map((customObj) =>
          `<span title="${customObj}">${_LeanData.Util.truncateText(customObj, 10)}</span>`)
          .join(' <span class="divider">/</span> ');
        group[0].categories = customObjectsStr;
        group[0].name = hoverText;
        optionsList.push(group[0]);
      }
    }
    rr = optionsList;
    options = nonRR.concat(rr);
  } 
  return options;
};

module.exports = { asyncServiceCallHelper };


