					convertLeadToContact: this.model.nodeInfo.convertLeadToContact,
					convertedLeadStatuses: actionNodeMetaData.convertedLeadStatuses,
					convertedLeadStatusApiNameToLabel: actionNodeMetaData.convertedLeadStatusApiNameToLabel,
					validateStatus: Magellan.Validation.validateConvertedLeadStatus.bind(this, this.model.nodeInfo["convert status"]),
          showRecordType: hasAccRecordType,
