        const isPrimaryDecisionNode = _LeanData._app.CLOAC_OBJECT_TYPES.includes(this.model.nodeInfo.objectType) || this.model instanceof _LeanData.GraphModels.Decision_Branch_Custom || this.model instanceof _LeanData.GraphModels.Decision_Branch_Prospect;
