  Magellan.Views.ScheduledRoutingEdgeSelector = Magellan.Views.ButtonHandler.extend({
    className: 'scheduled-routing-edge-selector collapsible-outer-container open',

    initialize: function(options) {
      this.dropdownReferences = [];
      this.jobIdToJobMap = {};
      this.applicableScheduledJobs = (_.cloneDeep(_LeanData.AppState.scheduledJobs || [])).filter((scheduledJob) => {
        this.jobIdToJobMap[scheduledJob.Id] = scheduledJob;
        return scheduledJob.nodeType === this.model.nodeInfo.type;
      });
      
      // Events to re-render dropdowns and validate
      this.listenTo(this.model, 'filterRuleChanged addRule', () => {
        this.refreshDropdowns();
      });
      this.listenTo(this.model, 'deleteRule', (deletedRule) => {
        // We do not clear out the Edge_Name__c value on scheduled jobs associated with this edge
        // This allows a renamed edge to be able to link to a scheduled job if renamed to the previously deleted edge
        this.refreshDropdowns();
      });
      this.listenTo(this.model, 'updateEdgeName', ({ previousValue, newValue }) => {
        // Update the edge reference for all scheduled jobs with previousEdgeName to the newEdgeName
        (_LeanData.AppState.scheduledJobs || []).forEach((scheduledJob) => {
          if (scheduledJob.edgeName === previousValue) {
            scheduledJob.edgeName = newValue;
          }
        });
        this.refreshDropdowns();
      });
      this.listenToOnce(this.model, 'saveNodeEvent', () => {
        // When node is saved, update the scheduledJobs in the appState
        // The app state variable will be used when saving the graph
        (_LeanData.AppState.scheduledJobs || []).forEach((scheduledJob) => {
          scheduledJob.edgeName = this.jobIdToJobMap[scheduledJob.Id].edgeName;
        });
      });
    },

    template: _.template(__webpack_require__(274)),

    refreshDropdowns: function() {
      this.dropdownReferences.forEach(($dropdown) => $dropdown.remove());
      this.dropdownReferences = [];

      const edgeList = this.model.nodeInfo.edges.map((edge) => edge.name);

      const _this = this;
      this.$el.find('.scheduled-job-row').each(function() {
        const jobId = $(this).data('id');
        const selectedEdgeName = _this.jobIdToJobMap[jobId].edgeName;

        $(this).find('.scheduled-job-edge-col').each(function() {
          const edgeDropdown = new Magellan.Views.LDDropdown({
            value: selectedEdgeName,
            options: edgeList,
            required: true,
            placeholder: 'None',
            onChange: (edge) => {
              _this.jobIdToJobMap[jobId].edgeName = edge;
            },
          });
          $(this).html(edgeDropdown.$el);
          _this.dropdownReferences.push(edgeDropdown);
        });
      });
    },

    render: function() {
      var content = this.template({
        applicableScheduledJobs: this.applicableScheduledJobs
      });
      this.$el.html(content);

      this.refreshDropdowns();
      
      return this;
    },
  });

