	Magellan.Views.CustomInterface = Magellan.Views.ButtonHandler.extend({
		initialize: function(options) {
      this.model.nodeInfo.nodeTypeToParametersmap = this.model.nodeInfo.nodeTypeToParametersmap ? this.model.nodeInfo.nodeTypeToParametersmap : {}
			this.model.nodeInfo.parameter = this.model.nodeInfo.parameter || "";
			this.model.nodeInfo.failureEdges = this.model.nodeInfo.failureEdges || [];
      this.customParameterChangedFlag = false;
		}, 

		template: _.template(__webpack_require__(266)),

    initializeOptionsAndEdges: function() {
      let selectedParameter = this.model.nodeInfo.parameter;
      let nodesAndEdges = actionNodeMetaData.customInterfaceNodesAndEdges;
      if (selectedParameter && selectedParameter !== '' && nodesAndEdges[selectedParameter]) {
        // initialize edges 
        let customNodeEdges = nodesAndEdges[selectedParameter];
        let edgeToEdgeNameMap = {};
        if (this.model.nodeInfo.edges) {
          this.model.nodeInfo.edges.forEach((edge) => {
            edgeToEdgeNameMap[edge.name] = edge;
          });
        }
          this.model.nodeInfo.edges = customNodeEdges.map((edgeName) => {
            if (edgeName in edgeToEdgeNameMap) return edgeToEdgeNameMap[edgeName];
            return {
              type: 'fixed',
							condition: edgeName,
							name: edgeName,
							target: -1,
            }  
          });
      }
    },

    renderFieldUpdater: function(parameter) { 

      //create empty map for each parameter in nodeType if index does not exist
      if (actionNodeMetaData.parametersMap[parameter] && !this.model.nodeInfo.nodeTypeToParametersmap[parameter]) {
        let newMap = {};
        newMap[parameter] = actionNodeMetaData.parametersMap[parameter].map((val) => {return {field: val, value: "", type: "STRING"}});
        this.model.nodeInfo.nodeTypeToParametersmap = newMap;
      }
      
      // already depoyed CI nodes will not have the type field populated
      for (let individualParams in this.model.nodeInfo.nodeTypeToParametersmap[parameter]){
        if (!this.model.nodeInfo.nodeTypeToParametersmap[parameter][individualParams]['type']) {
          this.model.nodeInfo.nodeTypeToParametersmap[parameter][individualParams]['type'] = 'STRING';
        }
      }
      
      //string field typing for now
      if(parameter !== '' && this.model.nodeInfo.nodeTypeToParametersmap[parameter] && this.model.nodeInfo.nodeTypeToParametersmap[parameter].length > 0) {
        var soFieldUpdater = new Magellan.Views.SOFieldUpdater({
          object: _LeanData.AppState.PrimarySObjectType, // this allows for merge fields
          fields: this.updatableFields, // this varaible updates type value in nodeTypeToParametersmap
          updates: this.model.nodeInfo.nodeTypeToParametersmap[parameter], 
          nodeModel: this.model,
          editable: false,
          customerParameters: true
        });
        this.$('.so-field-updater-container').html(soFieldUpdater.render().$el);
        soFieldUpdater.$el.on('SOFieldUpdater:change', this._setFieldUpdates.bind(this));

        // customize render
        this.$('.typeahead.typeahead-input').prop('disabled', true);
        this.$('.typeahead.typeahead-input').removeClass('input-invalid');
        this.$('.merge-field-insert-button-container').hide();
      }
    },

		updateCustomParameter: function(e){
			this.model.nodeInfo.parameter = $(e.currentTarget).val();
			this.customParameterChangedFlag = true;
			this.render();
		},

		updateCustomParameterTypeAhead: function(e, typeaheadSelector) {
			this.model.nodeInfo.parameter = typeaheadSelector.selection[0]['name'];
			this.customParameterChangedFlag = true;
			this.render();
		}, 

		additionalEvents: {
			"input .custom-interface-parameter" : "updateCustomParameter",
			"nestedTypeaheadSelector:select #customInterfaceNodeDropdown": "updateCustomParameterTypeAhead",
		}, 

		_setFieldUpdates: function(event, fieldUpdater) {
	      //update model field values for each custom node type
	      let currentParameter = this.model.nodeInfo.parameter;
        this.model.nodeInfo.nodeTypeToParametersmap[currentParameter] = fieldUpdater.val();
	    },

		render: function() {
			this.removeAllChildViews();
			var content = this.template({
				customParameter: this.model.nodeInfo.parameter,
				customInterfaceNodesAndEdges: actionNodeMetaData.customInterfaceNodesAndEdges,
				parametersMap: actionNodeMetaData.parametersMap
			});
			this.$el.html(content);

			var selectedParameter = this.model.nodeInfo.parameter;

			this.renderFieldUpdater(selectedParameter);
      this.initializeOptionsAndEdges();

      var customInterfaceNodeTypes = {'nodeTypes':[]};
      _.each(actionNodeMetaData.customInterfaceNodesAndEdges, (customNodeEdges, customNodeName) => {

				if (this.customParameterChangedFlag === true && customNodeName.indexOf('FailureEdges') !== -1 && customNodeName.substr(0, customNodeName.indexOf('FailureEdges')) === selectedParameter) {
					_.each(actionNodeMetaData.customInterfaceNodesAndEdges[customNodeName], (failureEdges, failureEdgeName) => {
						this.model.nodeInfo.failureEdges.push(failureEdges);
					});
				}

				if (customNodeName.indexOf('FailureEdges') === -1) {
					customInterfaceNodeTypes['nodeTypes'].push({'label':customNodeName,'name':customNodeName, 'value':customNodeName});
        }
      });
    

			this.customParameterChangedFlag = false;

			var customInterfaceNodeTypeahead = new Magellan.Views.NestedTypeaheadSelector({
				required: false,
		        disableBreadcrumbs: true,
		        requireSelectionFromData: true,
		        data: customInterfaceNodeTypes,
		        root: 'nodeTypes',
		        selection: this.model.nodeInfo.parameter == null ? '' : _LeanData.Util.convertStringSelectionToArray(this.model.nodeInfo.parameter)
		    });
			this.$el.find("#customInterfaceNodeDropdown").html(customInterfaceNodeTypeahead.$el);
      customInterfaceNodeTypeahead.$el.on('nestedTypeaheadSelector:select', this.updateCustomParameterTypeAhead.bind(this));

			var advancedSettingsView = new Magellan.Views.AdvancedSettings({model: this.model});
			this.childViews.push(advancedSettingsView);
			advancedSettingsView.openPanel = this.openPanel;
			this.$el.find("#advanced-settings-wrapper").html(advancedSettingsView.render().$el);
			return this;
		}
	});

