  Magellan.Views.RespectUserSchedules = Backbone.View.extend({
    template: _.template(__webpack_require__(250)),
    events: {
      'click .respect-schedules-cb': '_toggleForm',
      'click .schedule-type-cb': '_updateScheduleTypes',
    },

    initialize: function(options) {
      this.model = options.model || new Backbone.Model();
      this.respectSchedules = ['W','V','H','P']; // initial selection chooses all schedule types
      this.listenToOnce(this.model, 'saveNodeEvent', this._removeFallbackEdge);
    },

    _toggleForm: function(e) {
       var isChecked = $(e.target).prop('checked');

      this.$el.find('.schedule-types-container').prop('hidden', !isChecked);

      // If unchecked, remove respect schedules key from nodeinfo or set data back when re-checked
      if (!isChecked) {
        delete this.model.nodeInfo.respectSchedules;
        this._removeFallbackEdge();

      } else {
        this.model.nodeInfo.respectSchedules = this.respectSchedules;
        this._addFallbackEdge();
      }
    },

    _updateScheduleTypes: function(e) {
      var $target = $(e.target);
      var type = $target.data('type'); //schedule type keys ['W', 'V', 'P', 'H']
      var isChecked = $target.prop('checked');

      if (isChecked) {
        this.respectSchedules.push(type); // add schedule type to list
      } else {
        _.pull(this.respectSchedules, type); //remove this schedule type from list
      }

      if(_.isEmpty(this.respectSchedules)){
        this._resetRespectUserSchedulesView();
      }
    },

    _resetRespectUserSchedulesView: function() {
      this.$el.find('.respect-schedules-cb').prop('checked', false);
      this.$el.find('.schedule-types-container').prop('hidden', true);
      // back to default value of all schedule types selected
      this.respectSchedules = ['W','V','H','P'];
      this.respectSchedules.forEach( (scheduleType) => {
        this.$el.find('input[type=checkbox][data-type="' + scheduleType + '"]' ).prop('checked', true);
      });
      // remove key from nodeInfo and fallback edge(if unused) from node
      delete this.model.nodeInfo.respectSchedules;
      this._removeFallbackEdge();
    },

    _removeFallbackEdge: function() {
      var rerender = false;
      if(this.model.nodeInfo.hasOwnProperty('respectSchedules')) return; // if the node has respectSchedules key don't remove fallback edge
      // remove the fallback edge if there is no next node assigned
      this.model.nodeInfo.edges = this.model.nodeInfo.edges.filter( (edge) => {
        let unusedFallbackEdge = edge.condition === 'Out of User Schedule' && (edge.target === -1 || edge.target === null);
        rerender = unusedFallbackEdge || rerender; // render if we are removing the fallback edge
        return !unusedFallbackEdge;
      } );

      if (rerender) {
        this.model.trigger("renderNodeEdges", false);
        _LeanData.FlowBuilderGraph.nodeEditorCtrl.configChangeEmitter.emit({
          currentEdges: this.model.nodeInfo.edges,
        });
      }
    },

    _addFallbackEdge: function() {
      let insertionPoint = (edge) => (edge.condition === 'Inactive User' || edge.condition === 'Inactive Owner');
      let fallbackEdge = {'type': 'fixed', 'condition': 'Out of User Schedule', 'name': 'Out of User Schedule', 'target': null};
      
      // determine if the fallback edge already exists
      let foundFallback = this.model.nodeInfo.edges.find( (edge) => edge.condition === 'Out of User Schedule' );

      // add the fallback edge if it doesn't exist & render
      if (!foundFallback) {
        this.model.nodeInfo.edges.splice(_.findLastIndex(this.model.nodeInfo.edges, insertionPoint) + 1, 0, fallbackEdge);
        this.model.trigger("renderNodeEdges", true);
        _LeanData.FlowBuilderGraph.nodeEditorCtrl.configChangeEmitter.emit({
          currentEdges: this.model.nodeInfo.edges,
        });
      }
    },

    render: function() {
      var content = this.template();
      this.$el.html(content);

      if (this.model.nodeInfo.respectSchedules) {
        this.respectSchedules = this.model.nodeInfo.respectSchedules;
        this.$el.find('input[type=checkbox][data-type="respect-schedules-on"]' ).prop('checked', true);
        this.$el.find('.schedule-types-container').prop('hidden', false);
        this._addFallbackEdge();
      }
      // check all schedule types selected, if none defined in nodeInfo then default is all types selected
      this.respectSchedules.forEach( (scheduleType) => {
        this.$el.find('input[type=checkbox][data-type="' + scheduleType + '"]' ).prop('checked', true);
      });

      ld_initializeToolTip(this.$el.find('.respect-schedules-tooltip'), {
        title: 'Routing Schedule',
        body: '<p>Specify whether LeanData should only route to Users who are available. If the user is not available, the record will follow the “Out of User Schedule” edge.</p>' +
          '<p>Set up User Schedules under the <a target="_blank" href="/apex/Dashboard#people/users">People</a> section of LeanData. Each User can have one set of Working Hours and Holidays and multiple Vacations scheduled.</p>',
        clickableContent: true
      });
      return this;
    }
  });


