        this.model.set('matchedObjectTypes', nodesToCurrentNode.matched);
        this.model.set('createdObjectTypes', nodesToCurrentNode.created);
        this.model.set('triggeredObjectTypes', nodesToCurrentNode.triggered);
        if (this.createEventOn) this.renderCreateEvent();
