	Magellan.Views.SoqlRule = Magellan.Views.ButtonHandler.extend({
		initialize: function(options) {
			this.objectType = options.objectType;
      this.primaryObjectType = _LeanData.AppState.PrimarySObjectType || null;
      this.overrideLeftObjectType = options.overrideLeftObjectType || null;
			this.errorMessage = "";
		},

		additionalEvents: {
			"blur .change-parameter-input" : "callValidateSOQL"
		}, 

		callValidateSOQL: function() {
			var that = this;
			if (_.isEmpty(this.model.soqlCondition)) {
				that.model.isValid = false;
				that.errorMessage = "";
				that.$el.find(".soqlFeedback").text(that.errorMessage);
				return;
			}

      const paramsJSON = JSON.stringify({
        'match type': this.objectType,
        'query condition': this.model.soqlCondition,
        'primarySObjectType': this.primaryObjectType,
        'overrideLeftObjectType': this.overrideLeftObjectType
      });

			_LeanData.RemotingRouter.validateSOQL(paramsJSON)
      .then(function(result) {
        if (result.success) {
          that.model.isValid = true;
          that.render();
          that.$el.find(".soqlFeedback").text("");
          that.errorMessage = "";
          that.$el.trigger("LD_SoqlRule:changed", that);
        } else {
          const err = result.errorMessage || '';
          that.model.isValid = false;
          that.render();
          that.$el.find(".soqlFeedback").text(err);
          that.errorMessage = err;
          that.$el.trigger("LD_SoqlRule:changed", that);
        }
			});
		},

		template: _.template(__webpack_require__(255)),

		render: function() {

			var content = this.template({
				soqlCondition: this.model.soqlCondition, 
				description: this.model.description, 
				isValid: this.model.isValid
			});

			this.$el.html(content);

			return this;
		}
	});

	Magellan.Views.OptimaView = Magellan.Views.ButtonHandler.extend({
		initialize: function(options) {
			this.objectType = options.objectType;
      this.overrideObjectType = options.overrideObjectType;
      this.hideOptimaFields = options.hideOptimaFields || false;
		},
	
		template: _.template(__webpack_require__(242)),

    update: function(dropdownView, selection) {
      var selectedValue = selection.reduce(function(str, field) {
        if (str!== '') str += '.';

        if (field.type === 'REFERENCE')
            return str += _LeanData.Util.flattenReferenceAPIs(field.name);
        else
            return str += field.name;
      }, '');

      this.model['field'] = selectedValue;

      // if field is on some activity objects but not all, set flag for back-end to know which object
      // else, clear this flag so that switching a selection from a Task or Event field
      // to something else doesn't break on the back-end
      const currentActivityType = selection.reduce((activityType, field) => {
        if (['Task', 'Event'].includes(field.objectType)) {
          activityType = field.objectType;
        }
        return activityType;
      }, null);

      if (currentActivityType) {
        this.model.fieldObjectType = currentActivityType;
      } else {
        delete this.model.fieldObjectType;
      }
    },
		
		render: function() {
      var objectName = this.overrideObjectType || Magellan.Views.getAPIObjectNameFromObjectType(this.objectType);

      var optimaFields = _LeanData.MetaDataController.getOptimaFieldMetaData();

      if (this.hideOptimaFields) {
        optimaFields = _.mapValues(optimaFields, x => x.filter(f => (!('name' in f) || !f.name.startsWith('#'))));
      }

      var selectedFields = _LeanData.Util.convertFieldSelectionStringToArray(
        this.model['field'], 
        objectName, 
        _LeanData.MetaDataController.getOptimaFieldMetaDataMap()
      );

      var content = this.template({
        condition: this.model,
        optimaFields: optimaFields
      });
      
      this.$el.html(content);

			var optimaDropdown = new Magellan.Views.NestedTypeaheadSelector({
                data: optimaFields,
                root: objectName,
                onSelect: this.update.bind(this),
                required: true,
                currentTextValue: this.model['field'],
                selection: selectedFields
            });

			this.$('.nested-dropdown-container').html(optimaDropdown.$el);
      this.$el.trigger('parameter:update');

			return this;
		}
	});

