  // #Node_CreateOpportunity
	Magellan.Validation.validateCreateOpportunity = function(currentNode) {
    var deferred = $.Deferred();
    var coAsyncValidationCalls = [];
    var valid = true;

		// When node is first created, validate by choosing a field that isn't created until the Edit menu is opened for the first time
		if (!currentNode.nodeInfo.opportunityFields) {
			valid = false;
    }
    
    const recordTypePromise = $.Deferred();
    coAsyncValidationCalls.push(recordTypePromise);
    if (currentNode.nodeInfo.recordTypeId == null) {
      recordTypePromise.resolve(true);
    } else if (!_.isUndefined(currentNode.nodeInfo.recordTypeId)) {
      _LeanData.FlowBuilderController.queryRecordTypes(currentNode.nodeInfo.recordTypeId)
      .then(function(res) {
        const fieldMetaDataMap = _LeanData.MetaDataController.getFieldMetaDataMap();
        const hasOppRecordType = fieldMetaDataMap['Opportunity'] != null && fieldMetaDataMap['Opportunity'].hasOwnProperty('recordtypeid');
        if (res.length == 0 && hasOppRecordType) valid = false;
      })
      .finally(() => {
        recordTypePromise.resolve(true)
      });
    } else {
      valid = false;
      recordTypePromise.resolve(true);
    }

    if ((currentNode.nodeInfo.closeDays < 0 || currentNode.nodeInfo.closeDays === '') && (currentNode.nodeInfo.closeDate == null || currentNode.nodeInfo.closeDate == '' || !currentNode.nodeInfo.closeDate.match(/^([0][1-9]|[1][0-2])\/([0][1-9]|[1-2][0-9]|[3][0-1])\/\d{4}$/)) ) {
    	valid = false;
    }
		
		if(currentNode.nodeInfo.ownerAssignmentType == 'customUserField' && (currentNode.nodeInfo.customUserField == null || currentNode.nodeInfo.customUserField == '')){
	    valid = false;
    }

    _.each(currentNode.nodeInfo.opportunityFields, function(field) {
      if (field.readFieldOrValue == null || field.writeField == null || field.readFieldOrValue == '' || field.isValid == false) {
        valid = false;
      } else if (field.dataType && field.type == 'value') {
        valid = valid && Magellan.Validation.isValidValueOfType(field.dataType, field.readFieldOrValue);
        valid = valid && Magellan.Validation.isValidMergeFieldValue(currentNode.nodeInfo.name, field.readFieldOrValue, 'STRING', field.writeField);
        valid = valid && Magellan.Validation.metadataFieldExists('Opportunity', field.writeField);
      } else if (field.writeField === 'name') {
        var errorMessages = Magellan.Validation.isValidMergeFieldValueMessages(currentNode.nodeInfo.name, field.readFieldOrValue, "STRING", "opportunity.name");
        valid = valid && _.isEmpty(errorMessages);
      }

      if (!_.isEmpty(field.readFieldObjectType) && !_.isEmpty(field.type) && field.type === 'field') {
        valid = valid && Magellan.Validation.metadataFieldExists(field.readFieldObjectType, field.readFieldOrValue);
      }
    });

    const assignmentPromise = $.Deferred();
    coAsyncValidationCalls.push(assignmentPromise);
    if (currentNode.nodeInfo.ownerAssignmentType == 'accountTeamAssignment') {
      const hasProvisioningError = !_LeanData.FeatureProvisioning.isFeatureEnabled('NODE:ACCOUNT_TEAMS');
      if (hasProvisioningError) Magellan.Validation.nonUpgradedNodes[currentNode.nodeInfo.name] = currentNode;

      if (hasProvisioningError || currentNode.nodeInfo.ownerAssignmentValue == null || currentNode.nodeInfo.ownerAssignmentValue == '') valid = false;

      Magellan.Validation.validateAccountTeam(currentNode.nodeInfo.ownerAssignmentValue).then((isValid) => {
        valid = valid && isValid;
        assignmentPromise.resolve(isValid && valid);
      });

    } else if (currentNode.nodeInfo.ownerAssignmentType == 'explicitOwnerAssignment') {
    	if (currentNode.nodeInfo.ownerAssignmentValue == null || currentNode.nodeInfo.ownerAssignmentValue == '') {
        valid = false;
        assignmentPromise.resolve(false);
      }
      _LeanData.FlowBuilderController.queryUsers([currentNode.nodeInfo.ownerAssignmentValue]).then(function(res) {
        valid = res.length === 0 || !res[0].IsActive ? false : true;
        assignmentPromise.resolve(valid);
      });
    } else {
      assignmentPromise.resolve(valid);
    }

    // Call all async validation functions
    $.when(...coAsyncValidationCalls).always(function() {
      deferred.resolve(valid);
    });

		return deferred;
  }

  Magellan.Validation.validateConvert = async function (currentNode) {
      var valid = Magellan.Validation.validateConvertedLeadStatus(currentNode.nodeInfo['convert status']);

      if (!currentNode.nodeInfo.doNotCreateOpportunity) {
        const hasProvisioningError = !_LeanData.FeatureProvisioning.isFeatureEnabled('NODE:CREATE_OPPORTUNITY');
        if (hasProvisioningError) Magellan.Validation.nonUpgradedNodes[currentNode.nodeInfo.name] = currentNode;
        valid = valid && !hasProvisioningError;
      }

      if (currentNode.nodeInfo['explicit account conversion']) {
        await _LeanData.FlowBuilderController.queryAccounts([currentNode.nodeInfo["explicit account id"]]).then(function (accounts) {
          valid = valid && !_.isEmpty(accounts);
        });
      }

      return valid;
  };

	Magellan.Validation.validateMergeContact = function(currentNode) {
		var valid = Magellan.Validation.validateConvertedLeadStatus(currentNode.nodeInfo['merge status']);
		return valid;
	};

  Magellan.Validation.validateRoundRobin = async function (currentNode) {
    var rrPoolId = currentNode.nodeInfo["round robin id"];

    var valid = !_.isEmpty(rrPoolId) && Magellan.Validation.isValidUserAssignmentField(currentNode.nodeInfo['assignment field'], _LeanData.AppState.PrimarySObjectType);

    if (!valid) return valid;
    
    await _LeanData.FlowBuilderController.queryRoundRobinPools([rrPoolId]).then(function(rrPools) {
      const hasAdvancedRRFeaturesEnabled = _LeanData.AppState.PrimarySObjectType === 'Meeting' || _LeanData.FeatureProvisioning.isFeatureEnabled('FEATURE:ADVANCED_ROUND_ROBIN');
      valid  = rrPools.length > 0;
      rrPools.forEach((rrPool) => {
        const isProvisioned = hasAdvancedRRFeaturesEnabled || !_LeanData.Util.hasAdvancedRoundRobinFeatures(rrPool);
        if (!isProvisioned) Magellan.Validation.nonUpgradedNodes[currentNode.nodeInfo.name] = currentNode;
        valid = valid && isProvisioned && (_LeanData.AppState.businessUnitId ?
                                            rrPool.LD_Business_Unit__c === _LeanData.AppState.businessUnitId :
                                            rrPool.LD_Business_Unit__c === undefined);
      });
    });
    
    return valid;
  };

  Magellan.Validation.validateUpdatePrimary = function(currentNode) {
    var valid = true;

    if (_.isEmpty(currentNode.nodeInfo.updates) && _.isEmpty(currentNode.nodeInfo.assignmentRuleSelection)) {
      valid = false;
    }

    const variableName = _LeanData.Util.debracketize(currentNode.nodeInfo.variable) || _LeanData.Variables.getReservedVariableName('routed', _LeanData.AppState.PrimarySObjectType)
    if (!Magellan.Validation.isValidVariableSelection(currentNode.nodeInfo.name, variableName)) {
      return false;
    }
    const variable = _LeanData.AppState.getCurrentVariablesHandler().getVariableByName(variableName);

    var assignmentRulesIdMap = _LeanData.MetaDataController.getAssignmentRulesIdMap(variable.sObject);

    if (!_.isEmpty(currentNode.nodeInfo.assignmentRuleSelection) && actionNodeMetaData.allowAssignmentRule) {
      valid = valid && assignmentRulesIdMap.hasOwnProperty(currentNode.nodeInfo.assignmentRuleSelection);
    }

    _.each(currentNode.nodeInfo.updates, function(updateCondition) {
      const updateValue = updateCondition.value;
      const updateField = updateCondition.field;
      const updateFieldType = updateCondition.type;

      valid = valid && Magellan.Validation.metadataFieldExists(variable.sObject, updateField);
      if (!valid) return;

      // Merge field validation
      let isValidValue = Magellan.Validation.isValidMergeFieldValue(currentNode.nodeInfo.name, updateValue, updateFieldType, updateField);
      const mergeFields = (typeof updateValue === 'string' && updateValue.match(/{!([^}]+)}/gi)) || [];
      if (mergeFields.length > 0) {
        // Additional validation for value containing merge fields
        if (_LeanData._function.SFDC_TYPE_TO_GROUPING[updateFieldType] !== 'String' && mergeFields[0] !== updateValue) {
          // Since we don't allow concatenation for non-string type, the value should only have 1 merge field
          isValidValue = false;
        }
      } else if (isValidValue) {
        // Validate value with no merge fields, only if value is still valid -- 'isValidMergeFieldValue' already returns false if the update field is empty
        const isFieldRequired = !_LeanData.MetaDataController.getFieldMetaDataMap()[variable.sObject][updateField].isNillable;
        const isFieldEmpty = updateValue === '' || updateValue === null;
        let isValidValueOfType = !isFieldRequired && isFieldEmpty; // Optional fields that are empty should be considered valid
        if (!isValidValueOfType) {
          // If the field is not optional and empty, validate the value's type
          if (updateFieldType === 'PICKLIST') isValidValueOfType = true;
          else isValidValueOfType = Magellan.Validation.isValidValueOfType(updateFieldType, updateValue);
        }

        if ((isFieldRequired && isFieldEmpty) || !isValidValueOfType) {
          isValidValue = false;
        }
      }

      valid = valid && isValidValue;
    });

    return valid;
  };

  Magellan.Validation.isValidVariableSelection = function(nodeName, variableName) {
    //Any variable containing 'routed ' is valid since the primary is always accessible and we know a variable containing routed and a 'space' is the reserved variable for the primary
    if (variableName.includes(`routed ${_LeanData.AppState.PrimarySObjectType.toLowerCase()}`)) return true;
    if (_.isEmpty(Magellan.Validation.nodeNamesToVariableStatus)) {
      Magellan.Validation.getNodesToCurrentNode(nodeName);
    }
    return Magellan.Validation.nodeNamesToVariableStatus[nodeName] && variableName in Magellan.Validation.nodeNamesToVariableStatus[nodeName] && Magellan.Validation.nodeNamesToVariableStatus[nodeName][variableName];
  }

  Magellan.Validation.validateExplicitOwnerAssignment = function(currentNode) {
    const promise = $.Deferred();
    const variableName = _LeanData.Util.debracketize(currentNode.nodeInfo.variable) || _LeanData.Variables.getReservedVariableName('routed', _LeanData.AppState.PrimarySObjectType);

    const orgData = _LeanData._getOrganizationData();
    if (!variableName.startsWith('routed ') && !_LeanData.FeatureProvisioning.isFeatureEnabled('NODE:RELATED_RECORDS_UPDATE')) {
      Magellan.Validation.nonUpgradedNodes[currentNode.nodeInfo['name']] = currentNode;
      promise.resolve(false);
      return promise;
    }
    if (!Magellan.Validation.isValidVariableSelection(currentNode.nodeInfo.name, variableName)) {
      promise.resolve(false);
      return promise;
    }
    const variable = _LeanData.AppState.getCurrentVariablesHandler().getVariableByName(variableName);
    const variableObjectType = variable ? variable.sObject : _LeanData.AppState.PrimarySObjectType;
    if (_.isEmpty(currentNode.nodeInfo.assignmentType) || currentNode.nodeInfo.assignmentType === 'by user id') {
      let valid = typeof (currentNode.nodeInfo['explicit owner assignment id'] || null) === 'string' && !_.isEmpty(currentNode.nodeInfo['assignment field']) && Magellan.Validation.isValidUserAssignmentField(currentNode.nodeInfo['assignment field'], variableObjectType);

      if (currentNode.nodeInfo['explicit owner assignment id'] === 'None' && currentNode.nodeInfo['assignment field'] !== 'OwnerId') {
        promise.resolve(valid);
      } else {
        _LeanData.FlowBuilderController.queryOwners([currentNode.nodeInfo['explicit owner assignment id']])
        .then((res) => {
          valid = valid && res.length > 0;
          if (valid && !res[0].Id.startsWith('00G')) {
            valid = valid && res[0].IsActive;
          } else if (valid && res[0].Id.startsWith('00G')) {
            valid = valid && _LeanData.FBUtil.isObjectTypeQueueOwnable(variableObjectType) && currentNode.nodeInfo['assignment field'] === 'OwnerId';
          }
          promise.resolve(valid);
        });
      }
    } else if (currentNode.nodeInfo.assignmentType === 'user field') {
      const userFieldAsMergeField = currentNode.nodeInfo['user field'] || '';
      const userField = _LeanData.Util.debracketize(userFieldAsMergeField);
      let variableName = userField.split('.', 1)[0];
      let valid = !_.isEmpty(userField) && (userField.endsWith('id') || userField.endsWith('__c'))
          && Magellan.Validation.isValidVariableSelection(currentNode.nodeInfo.name, variableName)
          && Magellan.Validation.isValidMergeFieldValue(currentNode.nodeInfo.name, userFieldAsMergeField, 'STRING', 'Explicit Owner Assignment')
          && !_.isEmpty(currentNode.nodeInfo['assignment field']) 
          && Magellan.Validation.isValidUserAssignmentField(currentNode.nodeInfo['assignment field'], variableObjectType);
      promise.resolve(valid);
    }

    return promise;
  }

  Magellan.Validation.validateEdgeNames = function(currentNode) {
    var valid = true;
    if (!_.isArray(currentNode.nodeInfo.edges) || currentNode.nodeInfo.edges.length < 1) return valid;
    if (!(currentNode instanceof _LeanData.GraphModels.Decision_BranchNode || currentNode instanceof _LeanData.GraphModels.TriggerNode || currentNode instanceof _LeanData.GraphModels.Partner_ZoomInfo || currentNode instanceof _LeanData.GraphModels.ReroutingNode)) {
      return true;
    };

    var edgeNameMapping = {};

    for (var i = 0, l = currentNode.nodeInfo.edges.length; i < l; i++) {
      var edge = currentNode.nodeInfo.edges[i];
      if (!edge.hasOwnProperty('name')) continue;
      if (edgeNameMapping.hasOwnProperty(edge['name'].toLowerCase()) || edge['name'].trim() == "") {
        valid = false;
        break;
      } else {
        edgeNameMapping[edge['name'].toLowerCase()] = true;
      }
    }

    return valid;
  }
  /**
   * Validate partner update feature parameters
   * @param {String} actionType 
   * @returns boolean
   */
  Magellan.Validation.validatePartnerUpdateFP = function (actionType) {
    let partnerName = '';
    switch (actionType) {
      case 'Sendoso - Add Prospect to Touch':
        partnerName = 'sendosoAddProspectToTouch';
        break;
      case 'Kronologic - Book Meeting with AI':
        partnerName = 'kronologicAIScheduling';
        break;
    }
    return _LeanData.FeatureProvisioning.isFeatureEnabled(partnerName);
  }

  /**
   * Validate the HVS Add to Sequence node.
   */
  Magellan.Validation.validateHVSAddToSalesCadence = function (currentNode) {
    if (_LeanData.MetaDataController.getPartnerAuthorization('salesforce sales engagement')) {
      if (currentNode.nodeInfo.salesCadenceSelection.length === 0) return $.Deferred(deferred => deferred.resolve(false));
      const deferred = $.Deferred();

      // validate specific hvs user only if the radio button is selected
      let validateUserPromise;
      if (currentNode.nodeInfo.assigneeSelection === 'specific') {
        if (currentNode.nodeInfo.userSelection.length === 0) return $.Deferred(deferred => deferred.resolve(false));
        validateUserPromise = _LeanData.FlowBuilderController.hvs_validateHVSUser(currentNode.nodeInfo.userSelection);
      } else if (currentNode.nodeInfo.assigneeSelection === 'owner') {
        validateUserPromise = new Promise((resolve, reject) => resolve(true));
      } else if (currentNode.nodeInfo.assigneeSelection === 'customField') {
        validateUserPromise = new Promise((resolve, reject) => resolve(currentNode.nodeInfo.customUserField !== ''));
      }

      const validateSequencePromise = _LeanData.FlowBuilderController.hvs_validateSalesCadence(currentNode.nodeInfo.salesCadenceSelection);

      Promise.all([validateUserPromise, validateSequencePromise])
      .then(([userValid, sequenceValid]) => {
        deferred.resolve(userValid && sequenceValid);
      });

      return deferred;
    } else {
      return $.Deferred(deferred => deferred.resolve(false));
    }
  }

