  Magellan.Validation.validateOutreachCreateTask = function (currentNode) {
    const deferred = $.Deferred();

    if (_LeanData.MetaDataController.getPartnerAuthorization('outreach')) {
      const config = _LeanData.MetaDataController.getPartnerConfiguration('outreach');
      if (!(config.userIdField && config.accountIdField)) {
        return $.Deferred(deferred => deferred.resolve(false));
      }
      let validateUserPromise;
      if (currentNode.nodeInfo.assignToSelection === 'specificUser') {
        if (!currentNode.nodeInfo.explicitOwnerAssignmentSelection[0]) {
          return $.Deferred(deferred => deferred.resolve(false));
        }
        validateUserPromise = _LeanData.FlowBuilderController.outreach_validateOutreachUser(currentNode.nodeInfo.explicitOwnerAssignmentSelection[0]);
      } else if (currentNode.nodeInfo.assignToSelection === 'userField') {
        validateUserPromise = new Promise((resolve, reject) => {
          resolve(
            currentNode.nodeInfo.userField !== '' && 
            Magellan.Validation.isValidMergeFieldValue(currentNode.nodeInfo.name, currentNode.nodeInfo.userField, 'STRING','Outreach Create Task') &&
            _LeanData.Util.getMergeFieldSObjectType(currentNode.nodeInfo.userField)[0] === 'User'
          );
        });
      }

      //due date
      if (currentNode.nodeInfo.dueDateSelection === 'relative') {
        if (!currentNode.nodeInfo.dueDateValue || currentNode.nodeInfo.dueDateValue < 0) {
          return $.Deferred(deferred => deferred.resolve(false));
        }
      }
      //Task note has invalid field
      if(!Magellan.Validation.isValidMergeFieldValue(currentNode.nodeInfo.nodeName, currentNode.nodeInfo.taskNote, 'STRING', 'null'))
        return $.Deferred(deferred => deferred.resolve(false));

      Promise.all([validateUserPromise]).then(([userValid]) => {
        deferred.resolve(userValid);
      });
      return deferred;
    } else {
      return $.Deferred(deferred => deferred.resolve(false));
    }
  }

  /**
   * Validate the ZoomInfo Enrich node.
   */
  Magellan.Validation.validateZoominfoEnrichNode = function (currentNode, primarySObjectType) {
    return new Promise((resolve, reject) => {
      if (_LeanData.MetaDataController.getPartnerAuthorization('zoominfo')) {
        if (_LeanData.MetaDataController.getPartnerApplicableObjectTypes('zoominfo', new Set([primarySObjectType])).size === 0) {
          reject();
          return;
        }
        Promise.all([_LeanData.RemotingRouter.zoominfo_appInstalled()])
        .then(([installed]) => {
          if (!installed) {
            reject();
          } else {
            resolve(true);
          }
        })
        .catch((...errors) => {
          console.error(errors);
          reject();
        });
      } else {
        reject();
      }
    });
  }

