      this.membersWithConflictingSchedules = options.membersWithConflictingSchedules;
      this.poolIdsWithWeightingChanged = options.rrpModel ? options.rrpModel.poolIdsWithWeightingChanged : new Set();
      this.translateMemberWeightingFromServer();
      this.populateNextOwner();
      if (this.rrpModel) {
        this.poolIdToNextUpData[this.rrpModel.get('Id')] = ['', ''];
      } else {
        // Conditional members count is already initialized if user opens the edit members modal from the round robin pools creator page
        this.poolIds.forEach((id) => this.updatePoolConditionalMembersCount(id));
      }
