      let initialUserList = options.filteredUserList;
      if (Array.isArray(initialUserList)) {
        initialUserList = initialUserList.filter((member) => {
          if (member.Id != null && member.Id.startsWith('005')) return true;
          return false;
        })
      }
      this.filteredUserList = initialUserList;
