  this.dailyTimezoneDropdown.$el.on('nestedTypeaheadSelector:select', this.handleTimezoneChange.bind(this));

  if (this.weeklyTimezoneDropdown) this.weeklyTimezoneDropdown.remove();
  this.weeklyTimezoneDropdown = createTimezoneDropdown();
