                                objType: getSObjectTypeLabel(pool.attributes.Object_Type__c),
                                poolType: _.isEmpty(pool.attributes.Pool_Type__c) ? 'Standard' : (poolTypeToLabel[pool.attributes.Pool_Type__c ] ? poolTypeToLabel[pool.attributes.Pool_Type__c ] : _.capitalize(pool.attributes.Pool_Type__c)),
