          buName = pool.attributes.LD_Business_Unit__c ? (pool.attributes.buDeleted ? '<i>Deleted BU</i>': pool.attributes.buName) : 'BU Not Found';
          if (!pool.attributes.LD_Business_Unit__c) buName = '<i>' + buName + '</i>' + '<div class="alert-icon" style="margin-left: 5px;"></div>';
